function ScrollProgressBar() {
  const { scrollYProgress } = useScroll();
  const scaleY = useSpring(scrollYProgress, { stiffness: 80, damping: 30 });
  return (
      <motion.div className="fixed left-0 top-0 bottom-0 w-px z-50 origin-top"
                  style={{ scaleY, backgroundColor: MINT }} />
  );
}

// ─── Intro Overlay ────────────────────────────────────────────────────────────
function IntroOverlay() {
  const reduced = usePrefersReducedMotion();
  const [phase, setPhase] = useState<"playing" | "exit">("playing");
  useEffect(() => {
    if (reduced) { setPhase("exit"); return; }
    const t = setTimeout(() => setPhase("exit"), 4000);
    return () => clearTimeout(t);
  }, [reduced]);
  if (reduced) return null;
  return (
      <AnimatePresence>
        {phase !== "exit" && (
            <motion.div key="intro"
                        className="fixed inset-0 z-[100] flex flex-col items-center justify-center arch-grid overflow-hidden"
                        style={{ backgroundColor: GREEN }}
                        exit={{ y: "-100%" }}
                        transition={{ duration: 0.7, ease: [0.76, 0, 0.24, 1] }}>

              <motion.img src="/Logo_Animation-1.gif" alt="The Maram"
                          style={{ width: "clamp(200px, 35vw, 420px)", height: "auto" }}
                          initial={{ opacity: 0 }} animate={{ opacity: 1 }}
                          transition={{ duration: 0.4, delay: 0.4, ease: "easeOut" }} />
            </motion.div>
        )}
      </AnimatePresence>
  );
}

// ─── Nav ──────────────────────────────────────────────────────────────────────
function Nav() {
  const [scrolled, setScrolled] = useState(false);
  useEffect(() => {
    const handler = () => setScrolled(window.scrollY > 60);
    window.addEventListener("scroll", handler, { passive: true });
    return () => window.removeEventListener("scroll", handler);
  }, []);
  const links = [
    { label: "HOME", href: "#home" },
    { label: "ABOUT", href: "#about" },
    { label: "SERVICES", href: "#services" },
    { label: "CONTACT", href: "#contact" },
  ];
  return (
      <nav className="fixed top-0 left-0 right-0 z-40 flex items-center"
           style={{
             backgroundColor: scrolled ? "rgba(7,80,58,0.96)" : GREEN,
             backdropFilter: scrolled ? "blur(10px)" : "none",
             borderBottom: scrolled ? "1px solid rgba(249,249,249,0.06)" : "1px solid transparent",
             transition: "background-color 0.4s ease, border-color 0.4s ease",
             padding: "clamp(12px,1.6vw,20px) clamp(24px,4vw,56px)",
           }}>
        <div style={{ color: SNOW, width: "clamp(80px,9vw,120px)", flexShrink: 0 }}>
          <WordmarkSVG className="w-full h-auto" />
        </div>
        <div style={{ flex: 1, height: "1px", backgroundColor: "rgba(249,249,249,0.1)", margin: "0 clamp(16px,2.5vw,40px)" }} />
        <div className="hidden md:flex items-center" style={{ gap: "clamp(20px,2.8vw,44px)" }}>
          {links.map((l) => <NavLink key={l.label} href={l.href}>{l.label}</NavLink>)}
        </div>
      </nav>
  );
}

function NavLink({ href, children }: { href: string; children: React.ReactNode }) {
  const [hov, setHov] = useState(false);
  return (
      <a href={href}
         onMouseEnter={() => setHov(true)}
         onMouseLeave={() => setHov(false)}
         style={{
           color: hov ? SNOW : "rgba(249,249,249,0.38)",
           fontSize: "10px", letterSpacing: "0.2em",
           fontFamily: "'Nohemi', sans-serif", fontWeight: 300,
           textDecoration: "none", transition: "color 0.25s ease", position: "relative",
         }}>
        {children}
        <motion.span
            style={{ position: "absolute", bottom: "-2px", left: 0, height: "1px", backgroundColor: MINT, width: "100%", originX: 0 }}
            animate={{ scaleX: hov ? 1 : 0 }}
            transition={{ duration: 0.25, ease: [0.16, 1, 0.3, 1] }} />
      </a>
  );
}

