// ─── 5. Architecture ──────────────────────────────────────────────────────────
function ArchPhoto({ src, alt, caption, side, scrollScale, entryClip, entryDelay, inView }: {
  src: string; alt: string; caption: string; side: string;
  scrollScale: ReturnType<typeof useTransform<number[], number>>;
  entryClip: string; entryDelay: number; inView: boolean;
}) {
  const [hov, setHov] = useState(false);
  const [mousePos, setMousePos] = useState({ x: 50, y: 50 });
  const divRef = useRef<HTMLDivElement>(null);

  const onMove = useCallback((e: React.MouseEvent) => {
    if (!divRef.current) return;
    const r = divRef.current.getBoundingClientRect();
    setMousePos({ x: ((e.clientX - r.left) / r.width) * 100, y: ((e.clientY - r.top) / r.height) * 100 });
  }, []);

  return (
      <motion.div ref={divRef}
                  style={{ overflow: "hidden", position: "relative" }}
                  initial={{ clipPath: entryClip }}
                  animate={inView ? { clipPath: "inset(0 0% 0 0%)" } : {}}
                  transition={{ duration: 1.2, ease: [0.16, 1, 0.3, 1], delay: entryDelay }}
                  onMouseEnter={() => setHov(true)}
                  onMouseLeave={() => setHov(false)}
                  onMouseMove={onMove}>

        {/* Image — un-greys and zooms on hover */}
        <motion.img src={src} alt={alt}
                    style={{ width: "100%", height: "100%", objectFit: "cover", objectPosition: "center", scale: scrollScale }}
                    animate={{
                      filter: hov ? "grayscale(0%) contrast(1.02) brightness(1.0)" : "grayscale(100%) contrast(1.05) brightness(0.85)",
                      scale: hov ? 1.06 : 1,
                    }}
                    transition={{ duration: 0.9, ease: [0.16, 1, 0.3, 1] }} />

        {/* Mouse-follow parallax highlight */}
        <motion.div
            style={{ position: "absolute", inset: 0, pointerEvents: "none" }}
            animate={{ background: hov ? `radial-gradient(circle 45% at ${mousePos.x}% ${mousePos.y}%, rgba(70,174,135,0.10) 0%, transparent 70%)` : "transparent" }}
            transition={{ duration: 0.05 }} />

        {/* Mint border that traces in on hover */}
        <motion.div style={{ position: "absolute", inset: 0, pointerEvents: "none", border: `1px solid ${MINT}`, originX: 0, originY: 0 }}
                    animate={{ opacity: hov ? 0.35 : 0, scale: hov ? 1 : 1.04 }}
                    transition={{ duration: 0.5, ease: [0.16, 1, 0.3, 1] }} />

        {/* Caption — slides up on hover */}
        <motion.div
            animate={{ opacity: hov ? 1 : 0, y: hov ? 0 : 14 }}
            transition={{ duration: 0.4, ease: [0.16, 1, 0.3, 1] }}
            style={{ position: "absolute", bottom: 0, left: 0, right: 0, padding: "clamp(40px,5vw,60px) clamp(20px,2.5vw,32px) clamp(20px,2.5vw,32px)", background: "linear-gradient(to top, rgba(0,0,0,0.75) 0%, transparent 100%)", pointerEvents: "none" }}>
          <p style={{ color: SNOW, fontFamily: "'Nohemi', sans-serif", fontWeight: 300, fontSize: "clamp(8px,0.85vw,11px)", letterSpacing: "0.28em", textTransform: "uppercase", margin: 0 }}>
            {caption}
          </p>
        </motion.div>

        {/* Side label */}
        <div style={{ position: "absolute", top: "clamp(16px,2vw,24px)", [side]: "clamp(16px,2vw,24px)", pointerEvents: "none" }}>
          <motion.p animate={{ opacity: hov ? 0.7 : 0.18 }} transition={{ duration: 0.35 }}
                    style={{ color: MINT, fontFamily: "'Nohemi', sans-serif", fontWeight: 300, fontSize: "8px", letterSpacing: "0.32em", textTransform: "uppercase", margin: 0 }}>
            ✦ HOVER
          </motion.p>
        </div>
      </motion.div>
  );
}

