// ─── 8. Contact ───────────────────────────────────────────────────────────────
function ContactSection() {
  const ref = useRef(null);
  const inView = useInView(ref, { once: true, margin: "-5% 0px" });
  const [btnHov, setBtnHov] = useState(false);
  const btnMx = useMotionValue(0);
  const btnMy = useMotionValue(0);
  const btnSx = useSpring(btnMx, { stiffness: 250, damping: 22 });
  const btnSy = useSpring(btnMy, { stiffness: 250, damping: 22 });
  const btnRef = useRef<HTMLAnchorElement>(null);
  const reduced = usePrefersReducedMotion();

  const onBtnMove = useCallback((e: React.MouseEvent) => {
    if (reduced || !btnRef.current) return;
    const r = btnRef.current.getBoundingClientRect();
    btnMx.set((e.clientX - r.left - r.width / 2) * 0.28);
    btnMy.set((e.clientY - r.top - r.height / 2) * 0.28);
  }, [reduced, btnMx, btnMy]);

  const onBtnLeave = useCallback(() => { btnMx.set(0); btnMy.set(0); }, [btnMx, btnMy]);

  return (
      <section id="contact" ref={ref} className="arch-grid"
               style={{ backgroundColor: GREEN, minHeight: "100vh", display: "flex", flexDirection: "column" }}>
        <div style={{ flex: 1, display: "flex", flexDirection: "column", alignItems: "center", justifyContent: "center", padding: "clamp(80px,10vw,140px) clamp(24px,4vw,56px)", gap: "clamp(36px,5vw,60px)" }}>

          {/* Ghost BrandMark */}
          <motion.div
              style={{ color: "rgba(249,249,249,0.05)", width: "clamp(90px,14vw,180px)" }}
              initial={{ opacity: 0, scale: 0.7, rotate: -20 }}
              animate={inView ? { opacity: 1, scale: 1, rotate: 0 } : {}}
              transition={{ duration: 1.1, ease: [0.16, 1, 0.3, 1] }}>
            <BrandMarkSVG className="w-full h-auto" />
          </motion.div>

          {/* Magnetic CTA */}
          <motion.a
              ref={btnRef}
              href="mailto:abc@gmail.com"
              onMouseMove={onBtnMove}
              onMouseLeave={onBtnLeave}
              onMouseEnter={() => setBtnHov(true)}
              onMouseOut={() => setBtnHov(false)}
              initial={{ opacity: 0, scale: 0.88 }}
              animate={inView ? { opacity: 1, scale: 1, transition: { duration: 0.9, delay: 0.2, ease: [0.16, 1, 0.3, 1] } } : {}}
              whileHover={{ backgroundColor: "#0d0d0d", transition: { duration: 0.2 } }}
              style={{
                display: "inline-flex", alignItems: "center", justifyContent: "center",
                backgroundColor: "#000", color: SNOW,
                fontFamily: "'Nohemi', sans-serif", fontWeight: 400,
                fontSize: "clamp(18px,2.8vw,40px)", letterSpacing: "-0.01em",
                textDecoration: "none", padding: "clamp(14px,2vw,28px) clamp(32px,5.5vw,72px)",
                borderRadius: "9999px", textTransform: "uppercase",
                x: reduced ? 0 : btnSx, y: reduced ? 0 : btnSy,
              }}>
            Contact Me!
            <motion.span
                animate={{ x: btnHov ? 6 : 0, opacity: btnHov ? 1 : 0 }}
                transition={{ duration: 0.25 }}
                style={{ display: "inline-block", marginLeft: "12px", fontSize: "0.7em" }}>
              →
            </motion.span>
          </motion.a>

          {/* Tagline */}
          <FadeUp delay={0.4}>
            <p style={{ color: "rgba(249,249,249,0.22)", fontSize: "9px", letterSpacing: "0.32em", fontFamily: "'Nohemi', sans-serif", fontWeight: 300 }}>
              CLARITY BEFORE COMMITMENT
            </p>
          </FadeUp>
        </div>

        {/* Footer bar */}
        <div style={{ borderTop: "1px solid rgba(249,249,249,0.07)", padding: "clamp(18px,2.2vw,28px) clamp(24px,4vw,56px)", display: "flex", alignItems: "center", justifyContent: "space-between", gap: "24px", flexShrink: 0 }}>
          <p style={{ color: "rgba(249,249,249,0.4)", fontFamily: "'Nohemi', sans-serif", fontWeight: 300, fontSize: "clamp(10px,1vw,13px)", margin: 0 }}>
            Here Location Goes
          </p>
          <svg fill="none" viewBox="0 0 129.845 65.3674" style={{ width: "auto", height: "clamp(22px,2.8vw,34px)", flexShrink: 0 }}>
            <path d={svgPaths.p31744700} fill="rgba(249,249,249,0.3)" />
            <path d={svgPaths.p33e7ba40} fill="rgba(249,249,249,0.3)" />
            <path d={svgPaths.p3730dc00} fill="rgba(249,249,249,0.3)" />
          </svg>
          <p style={{ color: "rgba(249,249,249,0.4)", fontFamily: "'Nohemi', sans-serif", fontWeight: 300, fontSize: "clamp(10px,1vw,13px)", margin: 0 }}>
            abc@gmail.com
          </p>
        </div>
      </section>
  );
}

